import { describe, expect, it } from "vitest";
import { originalPosition, parseLocation } from "../src/index.js";

describe("parseLocation", () => {
  it("splits path, line and column", () => {
    expect(parseLocation("dist/assets/canvas-x1.js:412:17")).toEqual({
      path: "dist/assets/canvas-x1.js",
      line: 412,
      column: 17,
    });
    expect(parseLocation("nope")).toBeNull();
  });
});

describe("originalPosition", () => {
  // Generated by hand: line 1 maps col 0 → src/a.ts 1:1 and col 6 → src/a.ts 2:3 ("draw");
  // line 2 maps col 2 → src/b.ts 10:5. Fields carry across lines.
  const map = {
    sources: ["webpack://tool/./src/a.ts", "../src/b.ts"],
    names: ["draw"],
    mappings: "AAAA,MACEA;ECQE",
  };

  it("finds the last mapping on the line at or before the column", () => {
    expect(originalPosition(map, 1, 1)).toEqual({ source: "src/a.ts", line: 1, column: 1 });
    expect(originalPosition(map, 1, 10)).toEqual({ source: "src/a.ts", line: 2, column: 3, name: "draw" });
  });

  it("carries source fields from earlier lines", () => {
    expect(originalPosition(map, 2, 3)).toEqual({ source: "src/b.ts", line: 10, column: 5 });
  });

  it("is null before the first mapping on a line, or past the end", () => {
    expect(originalPosition(map, 2, 1)).toBeNull();
    expect(originalPosition(map, 9, 1)).toBeNull();
    expect(originalPosition({}, 1, 1)).toBeNull();
  });
});
